#!/bin/bash
# launch of p2-c-pilot_mb-znn on 2 slot(s) of NODE (default schrodinger): one queue per slot, 1 job each.
# Run on einstein AFTER: preflight ok, a line in phase2_exploration/SLOTS.md, the go of the orchestrator.
# Resume after any stop: run this script again (complete campaigns and done jobs are skipped).
NODE=${1:-schrodinger}
echo "qv2run jobs on $NODE now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pilot-mb; if [ -e /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane0.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane0.pid) 2>/dev/null; then echo lane 0 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane0.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-mb.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-02.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-04.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-06.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-08.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-10.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-12.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-14.json' > /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane0.log 2>&1 < /dev/null & echo lane 0 started; fi"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pilot-znn-00; if [ -e /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane1.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane1.pid) 2>/dev/null; then echo lane 1 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane1.pid; exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-03.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-05.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-07.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-09.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-11.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-13.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/pilot/p2-c-pilot-znn-15.json' > /home/scratch/jdochoa/drivers/p2-c-pilot_mb-znn_2slots_lane1.log 2>&1 < /dev/null & echo lane 1 started; fi"
